#include <Arduino.h>
#include "main.h"
#include "panel.h"
#include "ui.h"

// The Arduino contract: setup() runs once, loop() forever. The Rust templates split the same two halves into
// an Embassy main and a task, so a project of either language has one obvious place for "at power on" and
// one for "all the time".

void setup() {
    pinMode(25, OUTPUT); // the on-board LED
    panel_init();
    ui_init();

    Serial.begin(115200);
    Serial.println("Raspberry Pi Pico: designer ready");
}

void loop() {
    // The level is remembered here rather than read back: reading an output pin is not the same
    // thing on every chip.
    static bool ledOn = false;
    ledOn = !ledOn;
    digitalWrite(25, ledOn ? HIGH : LOW);
    ui_tick();
    delay(20);
}
